"use client";

import * as React from "react";
import { Bot, Circle, MoreVertical } from "lucide-react";
import { Card } from "@/components/aria/card";
import {
  DropdownMenu,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/aria/dropdown-menu";
import { Button } from "@/components/aria/button";
import { PnLBadge } from "@/components/moneytrees/pnl-badge";
import { TickerChart, type TickerPoint } from "@/components/moneytrees/ticker-chart";
import { cn } from "@/lib/utils";

type AgentStatus = "active" | "paused" | "liquidated";

type Props = {
  name: string;
  status: AgentStatus;
  mode: "paper" | "live";
  budget: number;
  balance: number;
  pnl: number;
  pnlPercent?: number;
  spark?: TickerPoint[];
  onPause?: () => void;
  onResume?: () => void;
  onEdit?: () => void;
  onKill?: () => void;
  onClick?: () => void;
  className?: string;
};

const statusColor: Record<AgentStatus, string> = {
  active: "text-[var(--color-bull)]",
  paused: "text-muted-foreground",
  liquidated: "text-[var(--color-bear)]",
};

export function AgentCard({
  name,
  status,
  mode,
  budget,
  balance,
  pnl,
  pnlPercent,
  spark,
  onPause,
  onResume,
  onEdit,
  onKill,
  onClick,
  className,
}: Props) {
  return (
    <Card
      className={cn("cursor-pointer p-card transition-colors hover:bg-accent/30", className)}
      onClick={onClick}
    >
      <div className="flex items-start justify-between gap-2">
        <div className="flex items-center gap-2 min-w-0">
          <div className="flex size-8 shrink-0 items-center justify-center rounded-md bg-[var(--color-gold-soft)] text-[var(--color-gold)]">
            <Bot className="size-4" />
          </div>
          <div className="min-w-0">
            <div className="flex items-center gap-1.5">
              <span className="truncate text-sm font-semibold">{name}</span>
              <Circle
                className={cn("size-2 fill-current", statusColor[status])}
                aria-label={status}
              />
            </div>
            <div className="text-xs text-muted-foreground capitalize">
              {mode} · {status}
            </div>
          </div>
        </div>
        <DropdownMenuTrigger>
          <Button
            variant="ghost"
            size="icon"
            className="size-7"
            onClick={(e) => e.stopPropagation()}
          >
            <MoreVertical className="size-4" />
          </Button>
          <DropdownMenu placement="bottom end">
            {status === "active" && onPause && (
              <DropdownMenuItem onAction={onPause}>Pause</DropdownMenuItem>
            )}
            {status === "paused" && onResume && (
              <DropdownMenuItem onAction={onResume}>Resume</DropdownMenuItem>
            )}
            {onEdit && <DropdownMenuItem onAction={onEdit}>Edit</DropdownMenuItem>}
            {onKill && (
              <>
                <DropdownMenuSeparator />
                <DropdownMenuItem onAction={onKill} className="text-[var(--color-bear)]">
                  Kill
                </DropdownMenuItem>
              </>
            )}
          </DropdownMenu>
        </DropdownMenuTrigger>
      </div>

      <div className="mt-3 grid grid-cols-3 gap-2 text-xs">
        <div>
          <div className="text-muted-foreground">Budget</div>
          <div className="mt-type-numeric">${budget.toLocaleString()}</div>
        </div>
        <div>
          <div className="text-muted-foreground">Balance</div>
          <div className="mt-type-numeric">
            ${balance.toLocaleString(undefined, { maximumFractionDigits: 2 })}
          </div>
        </div>
        <div>
          <div className="text-muted-foreground">P&amp;L</div>
          <PnLBadge value={pnl} percent={pnlPercent} size="sm" />
        </div>
      </div>

      {spark && spark.length > 0 && (
        <div className="mt-3">
          <TickerChart data={spark} variant="sparkline" height={32} />
        </div>
      )}
    </Card>
  );
}
